@Component
public class PagamentoPix implements FormaPagamentoStrategy {

    @Override
    public String codigo() {
        return "PIX";
    }

    @Override
    public boolean aceitaParcelas(int parcelas) {
        return parcelas == 1;
    }

    @Override
    public boolean disponivelParaTotal(BigDecimal total) {
        return true;
