1	package com.loja.checkout.service;
2	
3	import com.loja.checkout.domain.Regiao;
4	import com.loja.checkout.domain.clube.NivelClubeRegistro;
5	import com.loja.checkout.domain.clube.NivelClubeStrategy;
6	import com.loja.checkout.domain.cupom.CupomRegistro;
7	import com.loja.checkout.domain.cupom.CupomStrategy;
8	import com.loja.checkout.domain.entrega.ModalidadeEntregaRegistro;
9	import com.loja.checkout.domain.entrega.ModalidadeEntregaStrategy;
10	import com.loja.checkout.domain.pagamento.FormaPagamentoRegistro;
11	import com.loja.checkout.domain.pagamento.FormaPagamentoStrategy;
12	import com.loja.checkout.domain.pagamento.ResultadoPagamento;
13	import com.loja.checkout.dto.CheckoutRequest;
14	import com.loja.checkout.dto.CheckoutResponse;
15	import com.loja.checkout.dto.ItemDto;
16	import com.loja.checkout.exception.CheckoutException;
17	import org.springframework.stereotype.Service;
18	
19	import java.math.BigDecimal;
20	import java.math.RoundingMode;
21	import java.util.List;
22	
23	@Service
24	public class CheckoutService {
25	
26	    private final ModalidadeEntregaRegistro entregaRegistro;
27	    private final CupomRegistro cupomRegistro;
28	    private final NivelClubeRegistro clubeRegistro;
29	    private final FormaPagamentoRegistro pagamentoRegistro;
30	
31	    public CheckoutService(ModalidadeEntregaRegistro entregaRegistro,
32	                           CupomRegistro cupomRegistro,
33	                           NivelClubeRegistro clubeRegistro,
34	                           FormaPagamentoRegistro pagamentoRegistro) {
35	        this.entregaRegistro = entregaRegistro;
36	        this.cupomRegistro = cupomRegistro;
37	        this.clubeRegistro = clubeRegistro;
38	        this.pagamentoRegistro = pagamentoRegistro;
39	    }
40	
41	    public CheckoutResponse calcular(CheckoutRequest req) {
42	        // 1. PEDIDO_INVALIDO
43	        if (req.itens() == null || req.itens().isEmpty()) {
44	            throw new CheckoutException("PEDIDO_INVALIDO");
45	        }
46	        for (ItemDto item : req.itens()) {
47	            if (item.precoUnitario() == null || item.precoUnitario().signum() <= 0
48	                    || item.quantidade() == null || item.quantidade() <= 0
49	                    || item.pesoKg() == null || item.pesoKg().signum() <= 0) {
50	                throw new CheckoutException("PEDIDO_INVALIDO");
51	            }
52	        }
53	
54	        // 2. NIVEL_CLUBE_INVALIDO
55	        NivelClubeStrategy clube = clubeRegistro.buscar(req.nivelClube());
56	        if (clube == null) throw new CheckoutException("NIVEL_CLUBE_INVALIDO");
57	
58	        // 3. REGIAO_INVALIDA
59	        Regiao regiao = Regiao.buscar(req.regiao());
60	        if (regiao == null) throw new CheckoutException("REGIAO_INVALIDA");
61	
62	        // 4. MODALIDADE_INVALIDA
63	        ModalidadeEntregaStrategy modalidade = entregaRegistro.buscar(req.modalidadeEntrega());
64	        if (modalidade == null) throw new CheckoutException("MODALIDADE_INVALIDA");
65	
66	        // 5. MODALIDADE_INDISPONIVEL
67	        BigDecimal pesoTotal = calcularPesoTotal(req.itens());
68	        if (!modalidade.atende(pesoTotal)) throw new CheckoutException("MODALIDADE_INDISPONIVEL");
69	
70	        // subtotal necessário para validar cupom
71	        BigDecimal subtotal = calcularSubtotal(req.itens());
72	
73	        // 6. CUPOM_INVALIDO / 7. CUPOM_NAO_APLICAVEL
74	        CupomStrategy cupom = null;
75	        if (req.cupom() != null && !req.cupom().isBlank()) {
76	            cupom = cupomRegistro.buscar(req.cupom());
77	            if (cupom == null) throw new CheckoutException("CUPOM_INVALIDO");
78	            if (!cupom.aplicavel(subtotal)) throw new CheckoutException("CUPOM_NAO_APLICAVEL");
79	        }
80	
81	        // 8. FORMA_PAGAMENTO_INVALIDA
82	        FormaPagamentoStrategy pagamento = pagamentoRegistro.buscar(req.formaPagamento());
83	        if (pagamento == null) throw new CheckoutException("FORMA_PAGAMENTO_INVALIDA");
84	
85	        // 9. PARCELAMENTO_INVALIDO
86	        int parcelas = req.parcelas() != null ? req.parcelas() : 1;
87	        if (!pagamento.aceitaParcelas(parcelas)) throw new CheckoutException("PARCELAMENTO_INVALIDO");
88	
89	        // Cálculo: frete
90	        BigDecimal frete = clube.isentoFrete() ? new BigDecimal("0.00") : modalidade.calcularFrete(pesoTotal);
91	
92	        // Cálculo: desconto do cupom
93	        BigDecimal descontoCupom = cupom != null
94	                ? cupom.calcularDesconto(subtotal, frete, req.itens())
95	                : new BigDecimal("0.00");
96	
97	        // Cálculo: seguro (sobre subtotal bruto)
98	        BigDecimal seguro = subtotal.multiply(regiao.getTaxa()).setScale(2, RoundingMode.HALF_EVEN);
99	
100	        // Cálculo: total do pedido (antes do ajuste de pagamento)
101	        BigDecimal totalPedido = subtotal.subtract(descontoCupom).add(frete).add(seguro);
102	
103	        // 10. FORMA_PAGAMENTO_INDISPONIVEL
104	        if (!pagamento.disponivelParaTotal(totalPedido)) {
105	            throw new CheckoutException("FORMA_PAGAMENTO_INDISPONIVEL");
106	        }
107	
108	        // Cálculo: resultado do pagamento
109	        ResultadoPagamento resultado = pagamento.calcular(totalPedido, parcelas);
110	
111	        BigDecimal ajuste = resultado.totalFinal().subtract(totalPedido).setScale(2, RoundingMode.HALF_EVEN);
112	        BigDecimal credito = clube.calcularCredito(subtotal);
113	        boolean brinde = clube.contemBrinde(subtotal);
114	
115	        return new CheckoutResponse(
116	                subtotal,
117	                descontoCupom,
118	                frete,
119	                modalidade.prazoEntregaDias(),
120	                seguro,
121	                ajuste,
122	                resultado.totalFinal(),
123	                resultado.parcelas(),
124	                resultado.valorParcela(),
125	                credito,
126	                brinde);
127	    }
128	
129	    private BigDecimal calcularSubtotal(List<ItemDto> itens) {
130	        return itens.stream()
131	                .map(item -> item.precoUnitario().multiply(BigDecimal.valueOf(item.quantidade())))
132	                .reduce(BigDecimal.ZERO, BigDecimal::add)
133	                .setScale(2, RoundingMode.HALF_EVEN);
134	    }
135	
136	    private BigDecimal calcularPesoTotal(List<ItemDto> itens) {
137	        return itens.stream()
138	                .map(item -> item.pesoKg().multiply(BigDecimal.valueOf(item.quantidade())))
139	                .reduce(BigDecimal.ZERO, BigDecimal::add);
140	    }
