1	package com.loja.checkout.domain.pagamento.impl;
2	
3	import com.loja.checkout.domain.pagamento.FormaPagamentoStrategy;
4	import com.loja.checkout.domain.pagamento.ResultadoPagamento;
5	import org.springframework.stereotype.Component;
6	
7	import java.math.BigDecimal;
8	import java.math.MathContext;
9	import java.math.RoundingMode;
10	
11	@Component
12	public class PagamentoCartao implements FormaPagamentoStrategy {
13	
14	    private static final BigDecimal TAXA_MENSAL = new BigDecimal("0.0199");
15	    private static final MathContext MC = new MathContext(15, RoundingMode.HALF_EVEN);
16	
17	    @Override
18	    public String codigo() {
19	        return "CARTAO";
20	    }
21	
22	    @Override
23	    public boolean aceitaParcelas(int parcelas) {
24	        return parcelas >= 1 && parcelas <= 12;
25	    }
26	
27	    @Override
28	    public boolean disponivelParaTotal(BigDecimal total) {
29	        return true;
30	    }
31	
32	    @Override
33	    public ResultadoPagamento calcular(BigDecimal total, int parcelas) {
34	        if (parcelas <= 3) {
35	            BigDecimal valorParcela = total.divide(BigDecimal.valueOf(parcelas), 2, RoundingMode.HALF_EVEN);
36	            return new ResultadoPagamento(total, valorParcela, parcelas);
37	        }
38	
39	        // Tabela Price: parcela = P × i / (1 − (1 + i)^−n)
40	        BigDecimal potencia = BigDecimal.ONE.add(TAXA_MENSAL).pow(parcelas, MC);
41	        BigDecimal denominador = BigDecimal.ONE.subtract(BigDecimal.ONE.divide(potencia, MC), MC);
42	        BigDecimal valorParcela = total.multiply(TAXA_MENSAL, MC)
43	                .divide(denominador, 2, RoundingMode.HALF_EVEN);
44	        BigDecimal totalFinal = valorParcela.multiply(BigDecimal.valueOf(parcelas));
45	        return new ResultadoPagamento(totalFinal, valorParcela, parcelas);
46	    }
47	}
